<?php foreach(['first'=>'Première sonde (ancienne)','second'=>'Seconde sonde (ajoutée par toi)'] as $field=>$label):?><label><?=e($label)?><select name="<?=$field?>" required><option value="">Choisir un relevé</option><?php foreach($tdpSources as $source):if($field==='second'&&(string)$source['created_by']!==(string)$u['id'])continue;?><option value="<?=e((string)$source['id'])?>" <?=($comparison[$field]??'')===(string)$source['id']?'selected':''?>><?=e(combatDisplayDate($source['observed_at']))?> · RC #<?=e((string)$source['report_id'])?></option><?php endforeach;?></select></label><?php endforeach;?><button>Comparer les armées</button></form>
<?php if($comparison):?>
